package com.rpb.reservation.workforce;
import com.rpb.reservation.workforce.compliance.*;import static com.rpb.reservation.workforce.compliance.ComplianceDtos.*;
import com.rpb.reservation.workforce.application.*;import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.*;import java.math.BigDecimal;import java.time.*;
import org.junit.jupiter.api.*;import static org.assertj.core.api.Assertions.*;
class WorkforceCompliancePostgresTest extends WorkforcePostgresTest {
 ComplianceService service;ComplianceRepository policyRepo;UUID person;
 @BeforeEach void setupCompliance(){var mapper=new ObjectMapper().findAndRegisterModules();policyRepo=new ComplianceRepository(jdbc,new WorkforceJson(mapper));service=proxy(new ComplianceService(access,new ComplianceAccess(access,repository,directory),policyRepo,repository,new WorkforceAudit(logs,mapper),Clock.fixed(Instant.parse("2026-11-01T00:00:00Z"),ZoneOffset.UTC)));person=UUID.randomUUID();employees.save(admin,store,person,command(0,List.of(store,sibling),company,null,null));}
 Policy published(){var r=ComplianceReference.singapore();return service.savePolicy(admin,store,UUID.randomUUID(),new PolicyWrite(0L,"SG reviewed",LocalDate.of(2026,1,1),LocalDate.of(2028,12,31),true,r.rules(),r.sources()));}
 @Test void policyPublicationIsVersionedWithoutChangingAdoptedContract(){var p=published();var c=new ContractWrite(0L,LocalDate.of(2026,11,1),LocalDate.of(2026,10,1),p.id(),p.version(),new BigDecimal("8"),new BigDecimal("40"),new BigDecimal("5"),new BigDecimal("8"),new BigDecimal("44"),"workman","Verified contract duties and weekly hours");var id=UUID.randomUUID();var first=service.saveContract(admin,store,person,id,c);assertThat(service.saveContract(admin,store,person,id,c)).isEqualTo(first);var revised=service.savePolicy(admin,store,p.id(),new PolicyWrite(1L,"SG reviewed revised",p.effectiveFrom(),p.effectiveTo(),true,p.rules(),p.sources()));assertThat(revised.version()).isEqualTo(2);assertThat(policyRepo.policy(tenant,p.id(),1)).contains(p);assertThat(service.contracts(admin,store,person).items().getFirst().policyVersion()).isEqualTo(1);assertThat(first.partTime()).isFalse();}
 @Test void contractAndPolicyScopeRejectsLimitedManagerAndUnknownEmployee(){var limited=new com.rpb.reservation.walkin.api.CurrentActor(tenant,adminId,"staff",admin.roles(),admin.permissions(),Set.of(store));assertThatThrownBy(()->service.contracts(limited,store,person)).hasMessage("WORKFORCE_FORBIDDEN");assertThatThrownBy(()->service.contracts(admin,store,UUID.randomUUID())).hasMessage("WORKFORCE_NOT_FOUND");}
}
